import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();

            int left = Math.min(n, 5);
            int right = Math.max(0, n - 5);

            System.out.println(formatHand(left));
            System.out.println(formatHand(right));
        }
        scanner.close();
    }

    private static String formatHand(int fingers) {
        if (fingers == 0) {
            return "*";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < fingers; i++) {
            sb.append('I');
        }
        return sb.toString();
    }
}
